import{_ as t,o,c as e,ag as l}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"平常心","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-平常心.md","filePath":"50-概念资料/dict-平常心.md","lastUpdated":1778155802000}'),r={name:"50-概念资料/dict-平常心.md"};function i(n,a,u,s,c,h){return o(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="平常心" tabindex="-1">平常心 <a class="header-anchor" href="#平常心" aria-label="Permalink to &quot;平常心&quot;">​</a></h1><blockquote><p>传统：通用/儒家 | 佛家对应：清净心 | 道家对应：自然</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>平常心了空居士最常用的心法之一——无论顺境逆境，都保持内心平静、不惊讶、不慌乱、不狂喜的状态。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;司空见惯就是平常心。&quot;</p></blockquote><blockquote><p>&quot;顺境不沉溺，逆境不气馁——保持平常心。&quot;</p></blockquote><blockquote><p>&quot;保持平静的要诀就是保持理智地去看待一切。&quot;</p></blockquote><blockquote><p>&quot;不平静时问自己：&#39;我为什么要不平静？这样正确吗？&#39;&quot;</p></blockquote><h2 id="平常心-冷漠" tabindex="-1">平常心≠冷漠 <a class="header-anchor" href="#平常心-冷漠" aria-label="Permalink to &quot;平常心≠冷漠&quot;">​</a></h2><p>了空居士特别指出：<strong>平常心不是麻木</strong>。该高兴的时候高兴，该难过的时候难过，只是<strong>不被情绪拖着走</strong>。情绪来了，知道它来了；情绪走了，知道它走了。心里始终有一个&quot;知道&quot;。</p><h2 id="如何培养" tabindex="-1">如何培养 <a class="header-anchor" href="#如何培养" aria-label="Permalink to &quot;如何培养&quot;">​</a></h2><ol><li><strong>日常小练习</strong>：遇到意料之外的事，先深呼吸三次再说话</li><li><strong>不设预期</strong>：做最坏的打算，尽最大的努力</li><li><strong>不比较</strong>：不跟别人比，也不跟自己过去的巅峰比</li><li><strong>允许波动</strong>：情绪波动是正常的，平常心不是&quot;永远平静&quot;</li></ol><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-清净心">清净心</a> — 平常心就是清净心的日常表现</li><li><a href="/50-概念资料/dict-不二">不二</a> — 平常心是不二的实践</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 平常心的处世体现</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>每天提醒自己：平常心是道</li><li>好事来时不狂喜，坏事来时不崩溃</li><li>做该做的事，做完放下，如此而已</li></ul>',19)])])}const b=t(r,[["render",i]]);export{q as __pageData,b as default};
